#!/usr/bin/python3 -I
"""Génère /devhoros/php127/ext/idna_table_gen.go depuis unicodedata et idna.idnadata (python3).

Usage : gen_idna_table.py SORTIE.go
Chaque ligne de idnaBidiRanges est « DÉBUT;FIN;CLASSE » (hexadécimal) : plage maximale de points de code
de même classe directionnelle Bidi_Class (unicodedata.bidirectional), la classe L et les points non
attribués (classe vide) étant omis. Chaque ligne de idnaJoiningRanges est « DÉBUT;FIN;TYPE » : plage
maximale de même Joining_Type (D, R, L, C ou T) selon idna.idnadata.joining_types (ArabicShaping.txt et
dérivation T des catégories Mn, Me et Cf) ; le type U (non joignant) est omis.
"""
import sys
import unicodedata

import idna
import idna.idnadata


def ranges(classify):
    out = []
    for cp in range(0x110000):
        c = classify(cp)
        if out and out[-1][2] == c and out[-1][1] == cp - 1:
            out[-1][1] = cp
        else:
            out.append([cp, cp, c])
    return ["%X;%X;%s" % (lo, hi, c) for lo, hi, c in out if c]


def bidi(cp):
    c = unicodedata.bidirectional(chr(cp))
    return "" if c == "L" else c


def joining(cp):
    t = idna.idnadata.joining_types.get(cp)
    return chr(t) if isinstance(t, int) else (t or "")


out = [
    "// Code generated by ext/testdata/gen_idna_table.py from python3 unicodedata %s and idna %s; DO NOT EDIT."
    % (unicodedata.unidata_version, idna.__version__),
    "",
    "package ext",
    "",
    "const idnaBidiUnicodeVersion = \"%s\"" % unicodedata.unidata_version,
    "",
    "const idnaJoiningUnicodeVersion = \"%s\"" % idna.idnadata.__version__,
    "",
    "const idnaBidiRanges = `" + "\n".join(ranges(bidi)) + "`",
    "",
    "const idnaJoiningRanges = `" + "\n".join(ranges(joining)) + "`",
    "",
]
with open(sys.argv[1], "w", encoding="ascii") as f:
    f.write("\n".join(out))
